	@ParameterizedTest(name = "scan structure {0}")
	@ValueSource(strings = { "subject", "predicate", "object", "subject-object", "all" })
	void freshRepeatedScanReadsContextFromItsOwnQuadPosition(String shape) throws Exception {
		KernelCase test = kernelCase(shape, ContextConstraint.UNRESTRICTED);
		RowState row = row(EmptyBindingSet.getInstance());
		LmdbNativeKernelLowering.Lowered lowered = lower(test.pattern(), row);
		if (lowered == null) {
			assertFallbackRows(test, row, test.expected());
			return;
		}
		List<LmdbNativeKernelIr.Node> nodes = new ArrayList<>();
		LmdbNativeKernelIr.visitNodes(lowered.kernel.pipeline, nodes::add);
		List<LmdbNativeKernelIr.ScanQuad> scans = nodes.stream()
				.filter(LmdbNativeKernelIr.ScanQuad.class::isInstance)
				.map(LmdbNativeKernelIr.ScanQuad.class::cast)
				.toList();
		if (scans.isEmpty()) {
			assertNarrowPatternBridge(lowered, test.pattern());
			assertKernelRows(lowered, row, test.expected());
			return;
		}
		assertThat(scans).hasSize(1);
		LmdbNativeKernelIr.ScanQuad scan = scans.get(0);
		int first = switch (shape) {
		case "predicate" -> LmdbNativeKernelIr.ScanQuad.PRED;
		case "object" -> LmdbNativeKernelIr.ScanQuad.OBJ;
		default -> LmdbNativeKernelIr.ScanQuad.SUBJ;
		};
		int firstColumn = scan.outCols[first];
		int contextColumn = scan.outCols[LmdbNativeKernelIr.ScanQuad.CTX];
		assertThat(scan.terms[LmdbNativeKernelIr.ScanQuad.CTX])
				.as("the context cannot read a column before this same scan writes it")
				.isNull();
		assertThat(firstColumn).isNotNegative();
		assertThat(contextColumn).isNotNegative().isNotEqualTo(firstColumn);
		assertThat(nodes.stream()
				.filter(LmdbNativeKernelIr.FilterCompareId.class::isInstance)
				.map(LmdbNativeKernelIr.FilterCompareId.class::cast))
						.as("the actual context column is tied to the earlier occurrence")
						.anyMatch(filter -> !filter.negated && columnPair(filter, firstColumn, contextColumn));
		assertThat(nodes.stream()
				.filter(LmdbNativeKernelIr.FilterCompareId.class::isInstance)
				.map(LmdbNativeKernelIr.FilterCompareId.class::cast))
						.as("named-only filtering tests the actual context against physical zero")
						.anyMatch(filter -> filter.negated && comparesColumnToZero(filter, contextColumn, lowered));
	}

