	@Test
	void fixedDefaultDatasetArmsKeepPhysicalZeroDistinct() throws Exception {
		for (boolean both : List.of(false, true)) {
			long[] contexts = both ? new long[] { 0L, id(G1), id(G2) } : new long[] { 0L, id(G1) };
			PatternPlan pattern = new PatternPlan(Term.slot(0), Term.constant(id(P_SUBJECT)), Term.slot(1),
					Term.slot(0),
					new ContextConstraint(contexts), false, 10D);
			List<long[]> expected = both ? List.of(slots(G1, A, null), slots(G2, B, null))
					: List.of(slots(G1, A, null));
			assertPlanAndKernelRows(new KernelCase(pattern, expected), EmptyBindingSet.getInstance(), expected);

			SimpleDataset selection = new SimpleDataset();
			selection.addDefaultGraph(RDF4J.NIL);
			selection.addDefaultGraph(G1);
			if (both) {
				selection.addDefaultGraph(G2);
			}
			List<Map<String, Value>> expectedBindings = both
					? List.of(Map.of("g", G1, "x", A), Map.of("g", G2, "x", B))
					: List.of(Map.of("g", G1, "x", A));
			assertAcrossStrategies("selected default contexts " + both,
					() -> new StatementPattern(StatementPattern.Scope.DEFAULT_CONTEXTS, Var.of("g"),
							Var.of("p", P_SUBJECT, true, true), Var.of("x"), Var.of("g")),
					EmptyBindingSet.getInstance(), selection, expectedBindings, null);
		}
	}

	@Test
	void unaliasedNamedScanStillRunsBothKernelTiers() throws Exception {
		PatternPlan pattern = new PatternPlan(Term.slot(0), Term.constant(id(P_SUBJECT)), Term.slot(1), Term.slot(2),
				ContextConstraint.UNRESTRICTED, true, 10D);
		List<long[]> expected = List.of(slots(G1, A, G1), slots(G2, B, G2), slots(G1, C, G2), slots(D, D, G1));
		RowState row = row(EmptyBindingSet.getInstance());
		LmdbNativeKernelLowering.Lowered lowered = lower(pattern, row);
		assertThat(lowered).as("safe distinct context occurrences stay kernel-capable").isNotNull();
		assertThat(lowered.kernel.requirements.scans).isPositive();
		assertThat(lowered.bindings.planRequests).isEmpty();
		assertKernelRows(lowered, row, expected);
	}

	@ParameterizedTest(name = "caller {0} occurrence")
	@ValueSource(strings = { "subject", "predicate", "object", "subject-object", "all" })
	void genuineCallersConstrainEveryRepeatedOccurrence(String shape) {
		IRI first = shape.equals("all") ? G3 : G1;
		IRI second = shape.equals("all") ? G4 : G2;
		IRI missing = shape.equals("all") ? G1 : G3;
		List<Map<String, Value>> firstRows = resultRows(shape, first);
		List<Map<String, Value>> secondRows = resultRows(shape, second);
		List<Map<String, Value>> both = new ArrayList<>(firstRows);
		both.addAll(secondRows);
		assertAcrossStrategies(shape + " unbound", () -> algebra(shape, Var.of("g")),
				EmptyBindingSet.getInstance(), null, both, null);
		IRI caller = VF.createIRI(first.stringValue());
		assertAcrossStrategies(shape + " equal caller", () -> algebra(shape, Var.of("g")),
				binding("g", caller), null, firstRows, caller);
		assertAcrossStrategies(shape + " second caller", () -> algebra(shape, Var.of("g")),
				binding("g", second), null, secondRows, null);
		assertAcrossStrategies(shape + " unequal caller", () -> algebra(shape, Var.of("g")),
				binding("g", missing), null, List.of(), null);
		if (!shape.equals("all") && !shape.equals("subject-object")) {
			MapBindingSet conflict = binding("g", first);
			conflict.addBinding("x", D);
			assertAcrossStrategies(shape + " conflicting output", () -> algebra(shape, Var.of("g")),
					conflict, null, List.of(), null);
		}
	}

