	@Test
	void retainedDynamicContextSeparatesPresentNullNilAndHiddenProbe() {
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		QueryBindingSet presentNull = new QueryBindingSet();
		presentNull.setBinding("g", null);
		assertThat(presentNull.hasBinding("g")).isTrue();
		assertThat(presentNull.getValue("g")).isNull();
		BindingSet probe = BindingFrameBindings.push(new BindingFrameBindings.Scope(), EmptyBindingSet.getInstance(),
				binding("g", RDF4J.NIL), context);
		assertThat(probe.hasBinding("g")).isFalse();
		assertThat(BindingFrameBindings.probeValue(probe, "g")).isEqualTo(RDF4J.NIL);
		record Entry(String name, BindingSet input, List<Map<String, Value>> expected) {
		}
		List<Map<String, Value>> named = List.of(Map.of("g", G1, "x", A), Map.of("g", G2, "x", B));
		List<Entry> entries = List.of(
				new Entry("unbound", EmptyBindingSet.getInstance(), named),
				new Entry("rdf4j-nil", binding("g", RDF4J.NIL), List.of(Map.of("g", RDF4J.NIL, "x", A))),
				new Entry("present-null", presentNull, List.of()),
				new Entry("probe-only-nil", probe, named),
				new Entry("sesame-nil", binding("g", SESAME.NIL),
						List.of(Map.of("g", SESAME.NIL, "x", A), Map.of("g", SESAME.NIL, "x", B))),
				new Entry("ordinary-named", binding("g", G1), List.of(Map.of("g", G1, "x", A))),
				new Entry("rdf4j-nil-again", binding("g", RDF4J.NIL), List.of(Map.of("g", RDF4J.NIL, "x", A))));
		SoftAssertions softly = new SoftAssertions();
		for (Mode mode : List.of(new Mode("generic", generic),
				new Mode("native-generic-only", nativeStrategy.genericOnlyView()),
				new Mode("native-enabled", nativeStrategy))) {
			StatementPattern pattern = algebra("subject", Var.of("g"));
			pattern.setRuntimeTelemetryEnabled(true);
			pattern.setExecutionSummaryEnabled(true);
			QueryEvaluationStep prepared = mode.strategy().precompile(pattern, context);
			for (Entry entry : entries) {
				Observation actual = drain(prepared, pattern, entry.input());
				System.out.printf(
						"repeated-kernel retained case=%s mode=%s invocations=%d path=%s runtime=%s rows=%s%n",
						entry.name(), mode.name(), actual.nativeInvocations(), actual.path(), actual.runtime(),
						actual.rows());
				softly.assertThat(actual.rows())
						.as("%s / %s", entry.name(), mode.name())
						.containsExactlyInAnyOrderElementsOf(entry.expected());
				if (mode.name().equals("native-enabled") && entry.name().equals("ordinary-named")) {
					softly.assertThat(actual.nativeInvocations()).as("safe named entry opens native work").isPositive();
					softly.assertThat(actual.runtime()).as("safe named entry actually executes").contains("executed");
				}
			}
		}
		softly.assertAll();
	}

