	@ParameterizedTest(name = "authorized subject probe {0}")
	@ValueSource(strings = { "rdf4j", "sesame" })
	void authorizedNilSubjectProbeDoesNotBecomeAContextInput(String spelling) {
		IRI nil = spelling.equals("rdf4j") ? RDF4J.NIL : SESAME.NIL;
		Value object = spelling.equals("rdf4j") ? A : B;
		Value graph = spelling.equals("rdf4j") ? G1 : G2;
		List<Map<String, Value>> expected = List.of(Map.of("s", nil, "x", object, "g", graph));
		List<Map<String, Value>> all = List.of(Map.of("s", RDF4J.NIL, "x", A, "g", G1),
				Map.of("s", SESAME.NIL, "x", B, "g", G2), Map.of("s", G1, "x", C, "g", G1));
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingFrameBindings.Scope authorizedOwner = new BindingFrameBindings.Scope();
		BindingFrameBindings.Scope unregisteredOwner = new BindingFrameBindings.Scope();
		try (BindingFrameReplay.Invocation invocation = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
				null)) {
			invocation.root.registerLookupInputs(authorizedOwner, "s"::equals);
			BindingSet authorized = BindingFrameBindings.push(authorizedOwner, EmptyBindingSet.getInstance(),
					binding("s", nil), context, invocation.root);
			BindingSet unregistered = BindingFrameBindings.push(unregisteredOwner, EmptyBindingSet.getInstance(),
					binding("s", nil), context, invocation.root);
			assertThat(authorized.hasBinding("s")).isFalse();
			assertThat(BindingFrameBindings.hasLookupProbe(authorized, "s"::equals)).isTrue();
			assertThat(BindingFrameBindings.hasLookupProbe(unregistered, "s"::equals)).isFalse();
			SoftAssertions softly = new SoftAssertions();
			for (Mode mode : List.of(new Mode("generic", generic), new Mode("native-enabled", nativeStrategy))) {
				StatementPattern pattern = distinctContextProbePattern();
				pattern.setRuntimeTelemetryEnabled(true);
				pattern.setExecutionSummaryEnabled(true);
				softly.assertThat(BindingScopePolicy.statementBorrowedLookupNames(pattern))
						.contains("s")
						.doesNotContain("g");
				QueryEvaluationStep step = mode.strategy().precompile(pattern, context);
				softly.assertThat(BindingFrameBindings.supportsPhysicalLookups(step))
						.as("%s lookup", mode.name())
						.isTrue();
				Observation selected = drain(step, pattern, authorized);
				Observation unrestricted = drain(step, pattern, unregistered);
				softly.assertThat(selected.rows())
						.as("%s authorized NIL subject", mode.name())
						.containsExactlyInAnyOrderElementsOf(expected);
				softly.assertThat(unrestricted.rows())
						.as("%s unregistered NIL subject", mode.name())
						.containsExactlyInAnyOrderElementsOf(all);
				softly.assertThat(selected.bindingFrames())
						.as("%s retained authorized frame", mode.name())
						.containsOnly(true);
				softly.assertThat(selected.suppliedGraphs())
						.as("%s produced graph is not supplied", mode.name())
						.containsOnly(false);
				if (mode.name().equals("native-enabled")) {
					softly.assertThat(selected.nativeInvocations())
							.as("authorized subject opens native work")
							.isPositive();
					softly.assertThat(selected.runtime())
							.as("authorized subject executes natively")
							.contains("executed");
				}
			}
			softly.assertAll();
		}
	}

	@Test
	void authorizedContextProbesRemainHiddenForDistinctAndRepeatedOccurrences() {
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		BindingFrameBindings.Scope owner = new BindingFrameBindings.Scope();
		try (BindingFrameReplay.Invocation invocation = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
				null)) {
			invocation.root.registerLookupInputs(owner, "g"::equals);
			SoftAssertions softly = new SoftAssertions();
			for (String shape : List.of("distinct", "subject", "predicate", "object", "subject-object", "all")) {
				List<Map<String, Value>> expected = new ArrayList<>();
				if (shape.equals("distinct")) {
					expected.add(Map.of("s", RDF4J.NIL, "x", A, "g", G1));
					expected.add(Map.of("s", SESAME.NIL, "x", B, "g", G2));
					expected.add(Map.of("s", G1, "x", C, "g", G1));
				} else {
					expected.addAll(resultRows(shape, shape.equals("all") ? G3 : G1));
					expected.addAll(resultRows(shape, shape.equals("all") ? G4 : G2));
				}
				for (IRI nil : List.of(RDF4J.NIL, SESAME.NIL)) {
					BindingSet input = BindingFrameBindings.push(owner, EmptyBindingSet.getInstance(),
							binding("g", nil), context, invocation.root);
					softly.assertThat(input.hasBinding("g")).as("%s input is not a caller", shape).isFalse();
					softly.assertThat(BindingFrameBindings.hasLookupProbe(input, "g"::equals))
							.as("%s owner authorizes the probe", shape)
							.isTrue();
					for (Mode mode : List.of(new Mode("generic", generic),
							new Mode("native-enabled", nativeStrategy))) {
						StatementPattern pattern = shape.equals("distinct") ? distinctContextProbePattern()
								: algebra(shape, Var.of("g"));
						pattern.setRuntimeTelemetryEnabled(true);
						pattern.setExecutionSummaryEnabled(true);
						softly.assertThat(BindingScopePolicy.statementBorrowedLookupNames(pattern))
								.as("%s context is not a leaf lookup", shape)
								.doesNotContain("g");
						Observation actual = drain(mode.strategy().precompile(pattern, context), pattern, input);
						softly.assertThat(actual.rows())
								.as("%s / %s / %s", shape, nil, mode.name())
								.containsExactlyInAnyOrderElementsOf(expected);
						softly.assertThat(actual.bindingFrames())
								.as("%s / %s retained frame", shape, mode.name())
								.containsOnly(true);
						softly.assertThat(actual.suppliedGraphs())
								.as("%s / %s local graph", shape, mode.name())
								.containsOnly(false);
						if (mode.name().equals("native-enabled")) {
							softly.assertThat(actual.nativeInvocations())
									.as("%s opens native work", shape)
									.isPositive();
							softly.assertThat(actual.runtime()).as("%s executes natively", shape).contains("executed");
						}
					}
				}
			}
			softly.assertAll();
		}
	}

