		group.addGroupElement(new GroupElem("n", new Count(Var.of("x"), false)));
		group.setRuntimeTelemetryEnabled(true);
		group.setExecutionSummaryEnabled(true);
		QueryEvaluationStep groupStep = LmdbNativeAggregateCompiler.tryCompile(group, context, nativeStrategy, source);
		assertThat(groupStep).as("the ordinary Group uses its real native entry").isInstanceOf(NativeGroupStep.class);
		Observation grouped = drain(groupStep, group, input);
		System.out.printf("repeated-kernel direct Group nil=%s invocations=%d path=%s runtime=%s rows=%s%n",
				spelling, grouped.nativeInvocations(), grouped.path(), grouped.runtime(), grouped.rows());
		BindingSet graphFrame = GraphFrameBindings.supply(new QueryBindingSet(), "g", caller);
		Observation framed = drain(groupStep, group, graphFrame);
		System.out.printf("repeated-kernel framed Group nil=%s invocations=%d path=%s runtime=%s rows=%s%n",
				spelling, framed.nativeInvocations(), framed.path(), framed.runtime(), framed.rows());
