	@ParameterizedTest(name = "EXISTS caller {0}")
	@ValueSource(strings = { "rdf4j", "sesame" })
	void nilCallerIsPreservedAtExistsEntries(String spelling) {
		IRI nil = spelling.equals("rdf4j") ? RDF4J.NIL : SESAME.NIL;
		IRI caller = VF.createIRI(nil.stringValue());
		BindingSet input = binding("g", caller);
		QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
		StatementPattern witness = algebra("subject", Var.of("g"));
		witness.setRuntimeTelemetryEnabled(true);
		witness.setExecutionSummaryEnabled(true);
		QueryValueEvaluationStep direct = LmdbNativeAggregateCompiler.tryCompileExists(witness, context, nativeStrategy,
				source);
		assertThat(direct).as("ordinary repeated-pattern EXISTS has a native entry").isNotNull();
		SoftAssertions softly = new SoftAssertions();
		ScalarObservation safe = observeScalar("direct-safe-" + spelling, direct, witness, binding("g", G1));
		softly.assertThat(safe.value()).as("safe named EXISTS").isEqualTo(VF.createLiteral(true));
		softly.assertThat(safe.nativeInvocations())
				.as("the safe EXISTS invocation actually opens native work")
				.isPositive();
		StatementPattern genericWitness = algebra("subject", Var.of("g"));
		genericWitness.setRuntimeTelemetryEnabled(true);
		genericWitness.setExecutionSummaryEnabled(true);
		QueryValueEvaluationStep genericExists = generic.precompile(new Exists(genericWitness), context);
		softly.assertThat(observeScalar("generic-" + spelling, genericExists, genericWitness, input).value())
				.as("independent semantic EXISTS")
				.isEqualTo(VF.createLiteral(true));
		StatementPattern publicWitness = algebra("subject", Var.of("g"));
		publicWitness.setRuntimeTelemetryEnabled(true);
		publicWitness.setExecutionSummaryEnabled(true);
		QueryValueEvaluationStep publicExists = nativeStrategy.precompile(new Exists(publicWitness), context);
		softly.assertThat(observeScalar("public-" + spelling, publicExists, publicWitness, input).value())
				.as("public EXISTS")
				.isEqualTo(VF.createLiteral(true));
		softly.assertThat(observeScalar("direct-nil-" + spelling, direct, witness, input).value())
				.as("direct retained EXISTS caller")
				.isEqualTo(VF.createLiteral(true));
		MapBindingSet conflict = binding("g", caller);
		conflict.addBinding("x", D);
		softly.assertThat(observeScalar("direct-conflict-" + spelling, direct, witness, conflict).value())
				.as("EXISTS respects the other caller binding")
				.isEqualTo(VF.createLiteral(false));
		ScalarObservation safeAgain = observeScalar("direct-safe-again-" + spelling, direct, witness, binding("g", G1));
		softly.assertThat(safeAgain.value()).isEqualTo(VF.createLiteral(true));
		softly.assertThat(safeAgain.nativeInvocations())
				.as("the reused safe EXISTS invocation opens native work")
				.isPositive();
		softly.assertAll();
	}

	@Test
	void fullValueGroupKeepsOriginalNilFrameAndSafeNativeAlternative() throws Exception {
		SlowQueryContextHolder.SlowQueryContext previous = SlowQueryContextHolder.set(
				"repeated context full-value Group", Query.QueryType.TUPLE, "nestedLoop(fullValue),nestedLoop");
		try {
			SailDatasetTripleTermSource triples = new SailDatasetTripleTermSource(repository.getValueFactory(),
					dataset);
			LmdbNativeEvaluationStrategy forcedStrategy = (LmdbNativeEvaluationStrategy) new LmdbNativeEvaluationStrategyFactory(
					null).createEvaluationStrategy(null, triples, LmdbRepeatedContextTestSupport.statistics(store),
							store.getQueryExecutionPolicy());
			assertThat(forcedStrategy.forcedExecutionStrategyName()).isEqualTo("nestedLoop(fullValue),nestedLoop");
			StatementPattern input = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("g"),
					Var.of("p", P_SUBJECT, true, true), Var.of("fixed", A, true, true), Var.of("g"));
			Group group = new Group(input);
			GroupConcat concat = new GroupConcat(Var.of("g"));
			concat.setSeparator(new ValueConstant(VF.createLiteral("")));
			group.addGroupElement(new GroupElem("cat", concat));
			group.setRuntimeTelemetryEnabled(true);
			group.setExecutionSummaryEnabled(true);
			Extension consumer = new Extension(group,
					new ExtensionElem(new FunctionCall(FN.STRING_LENGTH.stringValue(), Var.of("cat")), "length"));
			QueryRoot root = new QueryRoot(
					new Projection(consumer, new ProjectionElemList(new ProjectionElem("length"))));
			NativeValuePositionAnalysis positions = NativeValuePositionAnalysis.analyze(root);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			QueryEvaluationStep compiled = forcedStrategy.withValuePositions(positions,
					() -> LmdbNativeAggregateCompiler.tryCompile(group, context, forcedStrategy, source));
			assertThat(compiled).isInstanceOf(NativeGroupStep.class);
			NativeGroupStep summary = (NativeGroupStep) compiled;
			assertThat(summary.requiresPhysicalResults()).isTrue();
			NativeGroupStep full = summary.fullValueAlternative();
			assertThat(full).as("the Group has its independently compiled FULL candidate").isNotNull();
			SoftAssertions softly = new SoftAssertions();
			for (Value graph : List.of(G1, RDF4J.NIL, SESAME.NIL)) {
				boolean safe = graph.equals(G1);
				IRI callerGraph = VF.createIRI(graph.stringValue());
				BindingSet caller = safe ? EmptyBindingSet.getInstance()
						: GraphFrameBindings.supply(new QueryBindingSet(), "g", callerGraph);
				Map<String, Value> expected = safe ? Map.of("cat", VF.createLiteral(G1.stringValue()))
						: Map.of("g", graph, "cat", VF.createLiteral(graph.stringValue()));
				Observation genericRows = observe(forcedStrategy.genericOnlyView(), group.clone(), caller, null);
				softly.assertThat(genericRows.rows())
						.as("independent FULL Group semantics %s", graph)
						.containsExactly(expected);
				Observation directFull = drainNative(full, group, caller);
				softly.assertThat(directFull.rows())
						.as("direct FULL alternative entry %s", graph)
						.containsExactly(expected);
				if (!safe) {
					softly.assertThat(directFull.graphValues())
							.as("direct FULL graph value %s", graph)
							.containsExactly(callerGraph);
					if (!directFull.graphValues().isEmpty()) {
						softly.assertThat(directFull.graphValues().get(0))
								.as("direct FULL caller value %s", graph)
								.isEqualTo(callerGraph);
					}
					softly.assertThat(directFull.suppliedGraphs())
							.as("direct FULL original graph frame %s", graph)
							.containsExactly(true);
				}
				List<LmdbNativeDecisionTestAccess.Selected> selected = new ArrayList<>();
				Observation selectedFull;
				try (AutoCloseable capture = LmdbNativeDecisionTestAccess.captureSelections(selected)) {
					selectedFull = drainNative(summary, group, caller);
				}
				softly.assertThat(selectedFull.rows()).as("selected Group entry %s", graph).containsExactly(expected);
				if (safe) {
					softly.assertThat(selected)
							.as("safe invocation actually selected the FULL candidate")
							.anyMatch(choice -> choice.target() == group && choice.point().equals("GROUP_PHYSICAL")
									&& choice.id().equals("nestedLoop(fullValue)"));
					softly.assertThat(selectedFull.path()).contains("nestedLoop(fullValue)");
				} else {
					softly.assertThat(selectedFull.graphValues())
							.as("selected Group caller value %s", graph)
							.containsExactly(callerGraph);
					if (!selectedFull.graphValues().isEmpty()) {
						softly.assertThat(selectedFull.graphValues().get(0))
								.as("selected caller value %s", graph)
								.isEqualTo(callerGraph);
					}
					softly.assertThat(selectedFull.suppliedGraphs())
							.as("selected Group original graph frame %s", graph)
							.containsExactly(true);
				}
				System.out.printf("repeated-kernel FULL graph=%s directInvocations=%d directPath=%s directRuntime=%s "
						+ "directRows=%s selectedInvocations=%d selected=%s selectedPath=%s selectedRuntime=%s "
						+ "selectedRows=%s%n", graph, directFull.nativeInvocations(), directFull.path(),
						directFull.runtime(), directFull.rows(), selectedFull.nativeInvocations(), selected,
						selectedFull.path(), selectedFull.runtime(), selectedFull.rows());
			}
			softly.assertAll();
		} finally {
			SlowQueryContextHolder.restore(previous);
		}
	}

